let previousFrame=performance.now(),hudClock=0;function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-previousFrame)/1000,.25);previousFrame=now;viewTime+=dt;if(mode==='multiplayer'){engine.update();return;}
  if(mode==='garage')showroomCamera();else{camera.clearViewOffset();updateRace(dt);if(mode!=='paused'){updateRacerModels(dt);updateCamera(dt);if(world)world.pads.forEach((p,i)=>p.children[0].material.emissiveIntensity=.3+Math.sin(viewTime*5+i)*.15);}hudClock+=dt;if(hudClock>.065){updateHud();hudClock=0;}}
  if(hornCaptionTime>0&&mode==='race'){hornCaptionTime-=dt;if(hornCaptionTime<=0)$('horn-caption').classList.add('hidden');}if(hitCaptionTime>0&&mode==='race'){hitCaptionTime-=dt;if(hitCaptionTime<=0)$('hit-caption').classList.add('hidden');}if(passengerCaptionTime>0&&mode==='race'){passengerCaptionTime-=dt;if(passengerCaptionTime<=0)$('passenger-caption').classList.add('hidden');}if(messageTimer>0){messageTimer-=dt;if(messageTimer<=0)$('race-message').classList.remove('visible');}engine.update();renderer.render(activeScene,camera);
}
